# Define the transform function
def transform(grid):
    rows = grid
    rows_count = len(rows)
    cols_count = len(rows[0]) if rows else 0

    # Background color is the corner color (top-left)
    bg_color = rows[0][0]

    # Find non-background colors
    non_bg_colors = {}
    for i, row in enumerate(rows):
        for val in row:
            if val != bg_color:
                if val not in non_bg_colors:
                    non_bg_colors[val] = True

    # Find secondary color: the one that is in a COMPLETE row
    for color in non_bg_colors:
        found_complete = False
        for i, row in enumerate(rows):
            if all(v == color for v in row):
                found_complete = True
                secondary_color = color
                break
        if found_complete:
            break

    # Get the pattern color
    pattern_color = -1
    for color in non_bg_colors:
        if color != bg_color and color != secondary_color:
            pattern_color = color
            break

    # Calculate new row color: secondary + 6, capped at 9
    new_color = min(secondary_color + 6, 9)

    # Find last row with pattern color
    last_pattern_row = -1
    for i, row in enumerate(rows):
        if pattern_color in row:
            last_pattern_row = i

    # Find first completely background row after last_pattern_row
    new_row_idx = -1
    for i in range(last_pattern_row + 1, rows_count):
        if all(v == bg_color for v in rows[i]):
            new_row_idx = i
            break

    # Create new grid
    new_grid = [list(row) for row in rows]
    if new_row_idx >= 0:
        new_grid[new_row_idx] = [new_color] * cols_count

    return new_grid

